:root {
  /* Tipografía */
  --stretch-font-family: "Segoe UI", Arial, sans-serif;
  --stretch-number-font: "IBM Plex Mono", Consolas, monospace;

  /* Textos */
  --stretch-text-primary: #000000;
  --stretch-text-secondary: #000000;

  /* Cuerda */
  --stretch-fiber-color: #0A638F;

  /* Poleas */
  --stretch-roller-fill: #D7D8DB;
  --stretch-roller-border: #4E4E4E;
  --stretch-roller-number: #000000;

  /* Cubas */
  --stretch-tank-fill: #D7D8DB;
  --stretch-tank-liquid: #A0CFE9;
  --stretch-tank-border: #223151;

  /* Tuberías */
  --stretch-steam-color: #930606;
  --stretch-condensate-color: #4E4E4E;

  /* Control */
  --stretch-control-color: #01524F;

  /* Válvulas */
  --stretch-valve-color: #0E0E55;

  /* Grosores */
  --stretch-fiber-width: 2.8px;
  --stretch-roller-border-width: 2.2px;
  --stretch-process-width: 1.6px;
  --stretch-process-main-width: 2px;
  --stretch-control-width: 1.6px;
  --stretch-tank-border-width: 1.4px;
  --stretch-valve-width: 1.4px;

  /* Numeración */
  --stretch-roller-number-size: 13px;
}

/* ==========================================================
   ENTORNO TRANSPARENTE
   ========================================================== */

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.stretch-widget {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  font-family: var(--stretch-font-family);
  pointer-events: none;
}

.stretch-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  shape-rendering: geometricPrecision;
}

/* Representación completamente estática */
.stretch-widget,
.stretch-widget * {
  animation: none !important;
  transition: none !important;
}

/* ==========================================================
   COLORES BASE DE LOS DEGRADADOS
   ========================================================== */

.roller-metal-base {
  stop-color: var(--stretch-roller-fill);
}

.tank-metal-base {
  stop-color: var(--stretch-tank-fill);
}

.tank-liquid-base {
  stop-color: var(--stretch-tank-liquid);
}

/* ==========================================================
   CUBAS: METAL SATINADO
   ========================================================== */

.tank-group {
  filter: url("#stretch2-tank-shadow");
}

.tank-upper {
  fill: url("#stretch2-tank-metal");
  stroke: none;
}

.tank-lower {
  fill: url("#stretch2-liquid-gradient");
  stroke: none;
  filter: url("#stretch2-liquid-inset");
}

.tank-outline {
  fill: none;
  stroke: var(--stretch-tank-border);
  stroke-width: var(--stretch-tank-border-width);
  stroke-linejoin: round;
}

.tank-top-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 0.7px;
  stroke-linecap: round;
  opacity: 0.48;
}

.tank-bottom-shade {
  fill: none;
  stroke: #555D69;
  stroke-width: 0.65px;
  stroke-linecap: round;
  opacity: 0.14;
}

/* ==========================================================
   CUERDAS
   ========================================================== */

.fiber {
  fill: none;
  stroke: var(--stretch-fiber-color);
  stroke-width: var(--stretch-fiber-width);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

/* ==========================================================
   POLEAS: SIN ANILLO INTERIOR
   ========================================================== */

.roller-body {
  fill: url("#stretch2-roller-metal");
  stroke: var(--stretch-roller-border);
  stroke-width: var(--stretch-roller-border-width);
  filter: url("#stretch2-roller-shadow");
}

.roller-label {
  fill: var(--stretch-roller-number);
  font-family: var(--stretch-number-font);
  font-size: var(--stretch-roller-number-size);
  font-weight: 700;
  text-anchor: middle;
  dominant-baseline: middle;
}

/* ==========================================================
   TUBERÍAS CONTINUAS
   ========================================================== */

.steam-line,
.condensate-line,
.control-line {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: none;
}

.steam-line {
  stroke: var(--stretch-steam-color);
  stroke-width: var(--stretch-process-width);
}

.condensate-line {
  stroke: var(--stretch-condensate-color);
  stroke-width: var(--stretch-process-width);
}

.steam-main,
.condensate-main {
  stroke-width: var(--stretch-process-main-width);
}

/*
 * La tubería termina exactamente en el borde de la válvula,
 * sin prolongar el trazo hacia su interior.
 */
.valve-connection {
  stroke-linecap: butt;
}

/* ==========================================================
   CONTROL
   ========================================================== */

.control-line {
  stroke: var(--stretch-control-color);
  stroke-width: var(--stretch-control-width);
}

.control-node {
  fill: var(--stretch-control-color);
  stroke: var(--stretch-control-color);
  stroke-width: 1px;
}

/* ==========================================================
   VÁLVULAS TRANSPARENTES
   ========================================================== */

.valve-body {
  fill: none;
  stroke: var(--stretch-valve-color);
  stroke-width: var(--stretch-valve-width);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.valve-link {
  fill: none;
  stroke: var(--stretch-valve-color);
  stroke-width: 0.7px;
  stroke-linecap: round;
}

.valve-dot {
  fill: var(--stretch-valve-color);
  stroke: var(--stretch-valve-color);
  stroke-width: 1px;
}

/* ==========================================================
   TEXTOS
   ========================================================== */

.labels text {
  font-family: var(--stretch-font-family);
}

.text-steam {
  fill: var(--stretch-steam-color);
  font-size: 12px;
  font-weight: 600;
}

.text-condensate {
  fill: var(--stretch-condensate-color);
  font-size: 12px;
  font-weight: 600;
}

.text-footer {
  fill: var(--stretch-text-secondary);
  font-size: 17px;
  font-style: italic;
  font-weight: 500;
}
